class Job:
    def __init__(self):
        self.queued = True
        self.running = False
        self.succeeded = False
        self.failed = False

    def state(self):
        if self.running:
            return "running"
        if self.failed:
            return "failed"
        if self.succeeded:
            return "succeeded"
        return "queued"

    def start(self):
        if not self.queued:
            raise ValueError("job is not queued")
        self.queued = False
        self.running = True

    def succeed(self):
        if not self.running:
            raise ValueError("job is not running")
        self.running = False
        self.succeeded = True

    def fail(self):
        if not self.running:
            raise ValueError("job is not running")
        self.running = False
        self.failed = True

class Job:
    def __init__(self):
        self._state = "queued"

    def state(self):
        return self._state

    def start(self):
        if self._state != "queued":
            raise ValueError("job is not queued")
        self._state = "running"

    def succeed(self):
        if self._state != "running":
            raise ValueError("job is not running")
        self._state = "succeeded"

    def fail(self):
        if self._state != "running":
            raise ValueError("job is not running")
        self._state = "failed"

    def pause(self):
        if self._state != "running":
            raise ValueError("job is not running")
        self._state = "paused"

    def resume(self):
        if self._state != "paused":
            raise ValueError("job is not paused")
        self._state = "running"

    def retry(self):
        if self._state != "failed":
            raise ValueError("job is not failed")
        self._state = "queued"

