import json
from pathlib import Path

class Catalog:
    def __init__(self):
        self.cache = {}

    def _read(self, path):
        path = Path(path)
        key = path.name
        modified = path.stat().st_mtime_ns
        if key not in self.cache or self.cache[key][0] != modified:
            self.cache[key] = (modified, json.loads(path.read_text()))
        return self.cache[key][1]["price"]

    def price(self, path):
        self._read(path)
        return self._read(path)

